#include <stdio.h>
#include <stdlib.h>
#include <math.h>
typedef struct{float x,y,z;}V;
typedef struct{V o,d;}R;
typedef struct{int h;float t;V p,n;}H;
static V sub(V a,V b){return(V){a.x-b.x,a.y-b.y,a.z-b.z};}
static float dotp(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
static V nrm(V a){float l=sqrtf(dotp(a,a));return(V){a.x/l,a.y/l,a.z/l};}
static union{unsigned u;float f;}SE,PE;
static float flr(float x){
 if(fabsf(x)>=8388608.0f)return x;
 int t=(int)x;float tf=(float)t;
 if(tf>x)tf-=1.0f;
 if((*(unsigned*)&x)&0x80000000)(*(unsigned*)&tf)|=0x80000000;
 return tf;
}
static int si(R r,V c,float rad,H*h){
 V oc=sub(r.o,c);float a=dotp(r.d,r.d),b=2*dotp(r.d,oc),cc=dotp(oc,oc)-rad*rad;
 float d=b*b-4*a*cc;if(d<0)return 0;
 float sq=sqrtf(d),t=(-b-sq)/(2*a);
 if(t<=SE.f)t=(-b+sq)/(2*a);
 if(t<=SE.f)return 0;
 h->h=1;h->t=t;h->p=(V){r.o.x+r.d.x*t,r.o.y+r.d.y*t,r.o.z+r.d.z*t};h->n=nrm(sub(h->p,c));return 1;
}
static V sky(V d){float t=(d.y+1)*.5f;return(V){1-.5f*t,1-.3f*t,1};}
static int shd(V p,V ldir,V sc,float rad){
 R sr={p,ldir};H h;return si(sr,sc,rad,&h);
}
static V tr(R r,V sc,float rad,V ldir){
 H h;
 if(si(r,sc,rad,&h)){
  int sd=shd(h.p,ldir,sc,rad);
  float df=sd?0:fmaxf(dotp(h.n,ldir),0);
  float col=.2f+.8f*df;
  return(V){col,.2f*col,.2f*col};
 }
 if(r.d.y>-PE.f)return sky(r.d);
 float t=-1.5f/r.d.y;
 if(t<=PE.f)return sky(r.d);
 V p=(V){r.o.x+r.d.x*t,r.o.y+r.d.y*t,r.o.z+r.d.z*t};
 V n=(V){0,1,0};
 int sd=shd(p,ldir,sc,rad);
 float df=sd?0:fmaxf(dotp(n,ldir),0);
 double fx=(double)flr(p.x),fz=(double)flr(p.z);
 int par=(int)(fx+fz);
 float chk=(par&1)?.4f:.9f;
 float col=chk*(.2f+.8f*df);
 return(V){col,col,col};
}
int main(){
 SE.u=0x3883126f;PE.u=0x38d1b717;
 int W=800,H=600;
 V sc=(V){0,-.5f,-5};
 V ldir=nrm((V){1,1,-1});
 union{unsigned u;float f;}c1;c1.u=0x3faaaaab;
 union{unsigned u;float f;}sc2;sc2.u=0x437ffd71;
 float scale=sc2.f;
 float(*img)[3]=malloc(H*W*12);
 fprintf(stderr,"Creating high-resolution image: %dx%d\n",W,H);
 fprintf(stderr,"This will be downsampled with ffmpeg after rendering\n");
 fprintf(stderr,"Rendering high-resolution image...\n");
 for(int y=0;y<H;y++){
  fprintf(stderr,"Progress: %.1f%%\n",(float)y*100.f/599.f);
  for(int x=0;x<W;x++){
   float dx=(float)x/799.f*2.6666667f-c1.f;
   float dy=1.f-(float)y/300.f;
   V d=nrm((V){dx,dy,-1});
   R r={(V){0,0,0},d};
   V c=tr(r,sc,1.f,ldir);
   float*p=img[y*W+x];p[0]=c.x;p[1]=c.y;p[2]=c.z;
  }
 }
 fprintf(stderr,"Rendering complete\n");
 FILE*f=fopen("image.ppm","w");fprintf(f,"P3\n%d %d\n255\n",W,H);
 for(int y=0;y<H;y++)for(int x=0;x<W;x++){float*p=img[y*W+x];
  double r=fmin(fmax((double)p[0],0),1.0);
  double g=fmin(fmax((double)p[1],0),1.0);
  double b=fmin(fmax((double)p[2],0),1.0);
  int ri=(int)((float)r*scale),gi=(int)((float)g*scale),bi=(int)((float)b*scale);
  fprintf(f,"%d %d %d\n",ri,gi,bi);}
 fclose(f);
 free(img);
 fprintf(stderr,"Wrote image to image.ppm\n");fprintf(stderr,"Done.\n");return 0;
}
CEOF
